exercises.solution:
const frutas = [
  { nome: 'Manga', preco: 9.5, quilos: 12 },
  { nome: 'Banana', preco: 4, quilos: 30 },
  { nome: 'Uva', preco: 14, quilos: 5 },
  { nome: 'Laranja', preco: 3.5, quilos: 25 },
];

const selecionadas = frutas.filter((fruta) => fruta.preco > 8);
const quilos = selecionadas.reduce((total, fruta) => total + fruta.quilos, 0);

console.log(`Frutas selecionadas: ${selecionadas.length}`);
console.log(`Quilos vendidos: ${quilos}`);
